using Game.UI.Runtime;
using System;using System.IO;using System.Linq;using System.Collections.Generic;using Game.Runtime;using Game.Components;using Game.Configs;using Game.Skirmish.Contracts;using Game.UI.Contracts;using Unity.Entities;using UnityEngine;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
internal static class PaidCategoryGuardControls {
 static readonly JArray Cases=new JArray();static void Check(bool b,string m){if(!b)throw new InvalidOperationException(m);}static void Case(string name,Action a){a();Cases.Add(new JObject{["name"]=name,["passed"]=true});}
 static void Reject<T>(Action a,string message)where T:Exception{try{a();}catch(Exception e){Check(e.GetType()==typeof(T)&&e.Message==message,"Wrong original rejection: "+e);return;}throw new Exception("Missing rejection: "+message);}
 static CatalogPublicFacts Facts()=>new CatalogPublicFacts(true,false,default,null,false,default,true,default,true,default);
 static CatalogUnitAuthoringValues Unit(string key)=>new CatalogUnitAuthoringValues(true,key,"finite owner control",true,1,1f,new Vector2Int(1,1),null,null,null,false,false,0,false,0,true,1,1f,1f,100,1,null,0,0,0,false,false);
 static int Main(string[] args){try{if(args.Length!=3||File.Exists(args[2]))throw new ArgumentException("initialization path/SHA/fresh result required");var initial=JObject.Parse(System.Text.Encoding.UTF8.GetString(AutonomousWorld.PinnedFile(args[0],args[1],4*1024*1024)),new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});var compiled=AutonomousWorld.ReadCompiledInitialization(initial);var setup=compiled.setup;var roles=setup.RoleOverlays.Where(x=>compiled.definition.ArmyProfileConfig.Allows(x.RoleId)).ToDictionary(x=>SkirmishRoleCatalogConfig.RuntimePrefabKey(x.RoleKind),x=>x,StringComparer.Ordinal);var catalog=new SkirmishProductionCatalog(setup,roles,true);string key=SkirmishRoleCatalogConfig.RuntimePrefabKey(SkirmishRoleKind.Rifle);var prefab=new LogicalCatalogPrefab("finite:rifle",key,true,Unit(key),true,null);var registry=new SourceCatalogRegistry(true,new[]{prefab},Array.Empty<LogicalCatalogPrefab>());var overlay=new SourceCatalogRegistry(true,new[]{prefab},Array.Empty<LogicalCatalogPrefab>());var store=new CatalogPrefabStore(SourceCatalogOrigin.ConfigInitializedMission,true,new[]{prefab},registry,registry,true,overlay);var em=new EntityManager();var session=new Entity{Index=1,Version=1};em.ImportEntity(session);em.AddComponentData(session,new SkirmishMatchState{Phase=SkirmishPhase.Playing});em.AddComponentData(session,new SkirmishExpandedSessionComponent{Phase=SkirmishSessionPhase.Playing});em.AddComponentData(session,new SkirmishProductionCatalogRecord{Catalog=catalog});var rows=new SourceCatalogRows(em,session,store);var facts=Facts();BuildDrawerCatalogItem selected=default;
 Case("original actualsetup and finite configured rifle category",()=>{var a=rows.Read(BuildDrawerCategory.Soldiers,facts);Check(a.Length==1&&ReferenceEquals(a[0].Prefab,prefab),"Actual original category/role metadata");selected=a[0];});
 Case("invalid category original guard",()=>Reject<NotSupportedException>(()=>rows.Read(unchecked((BuildDrawerCategory)999),facts),"Exact source category required"));
 Case("unknown expanded phase original guard",()=>{var s=em.GetComponentData<SkirmishExpandedSessionComponent>(session);var bad=s;bad.Phase=SkirmishSessionPhase.Spawning;em.SetComponentData(session,bad);try{Reject<NotSupportedException>(()=>rows.Read(BuildDrawerCategory.Soldiers,facts),"Exact current Playing S002 source match/session/catalog singleton required");}finally{em.SetComponentData(session,s);}});
 Case("changed catalog identity original guard",()=>{var old=em.GetComponentObject<SkirmishProductionCatalogRecord>(session);em.SetComponentData(session,new SkirmishProductionCatalogRecord{Catalog=new SkirmishProductionCatalog(setup,roles,true)});try{Reject<NotSupportedException>(()=>rows.Read(BuildDrawerCategory.Soldiers,facts),"Source production catalog reference changed");}finally{em.SetComponentData(session,old);}});
 Case("nested metadata scope original guard and ownership",()=>{using(var outer=new CatalogMetadataReadScope(em,store,facts,catalog)){Reject<NotSupportedException>(()=>rows.Read(BuildDrawerCategory.Soldiers,facts),"Nested source catalog context unsupported");Check(ReferenceEquals(CatalogMetadataReadScope.Current,outer),"Original outer scope retained");}Check(CatalogMetadataReadScope.Current==null,"Scope disposed");});
 Case("metadata admission failure stays exact",()=>Reject<NotSupportedException>(()=>new CatalogUnitAuthoringValues(false,"x","x",true,1,1,new Vector2Int(1,1),null,null,null,false,false,0,false,0,true,1,1,1,100,1,null,0,0,0,false,false),"Complete source-resolved config or reference authoring getters required"));
 Case("unit-only building domain remains unsupported",()=>{var m=new EntityManager();var e=new Entity{Index=2,Version=1};m.ImportEntity(e);m.AddComponentData(e,new SkirmishMatchState{Phase=SkirmishPhase.Playing});m.AddComponentData(e,new SkirmishExpandedSessionComponent{Phase=SkirmishSessionPhase.Playing});m.AddComponentData(e,new SkirmishProductionCatalogRecord{Catalog=catalog});var st=CatalogPrefabStore.FromResolvedConfiguredUnits(new[]{prefab},new[]{prefab});var rr=new SourceCatalogRows(m,e,st);Reject<NotSupportedException>(()=>rr.Read(BuildDrawerCategory.Buildings,facts),"Consumed building/restricted provider requires its actual configured source; unknown is not absence");});
#if PAID_OBSERVED_CATEGORY_CANDIDATE
 Case("exact exception parity after phase mutation",()=>{var observed=rows.ReadObserved(BuildDrawerCategory.Soldiers,facts);var old=em.GetComponentData<SkirmishExpandedSessionComponent>(session);var bad=old;bad.Phase=SkirmishSessionPhase.Spawning;em.SetComponentData(session,bad);try{Exception a=null,b=null;try{rows.Read(BuildDrawerCategory.Soldiers,facts);}catch(Exception e){a=e;}try{rows.ContainsCurrentSelection(selected,facts,observed);}catch(Exception e){b=e;}Check(a!=null&&b!=null&&a.GetType()==b.GetType()&&a.Message==b.Message,"exact phase exception parity");}finally{em.SetComponentData(session,old);}});
 Case("exact exception parity after catalog identity mutation",()=>{var observed=rows.ReadObserved(BuildDrawerCategory.Soldiers,facts);var old=em.GetComponentObject<SkirmishProductionCatalogRecord>(session);em.SetComponentData(session,new SkirmishProductionCatalogRecord{Catalog=new SkirmishProductionCatalog(setup,roles,true)});try{Exception a=null,b=null;try{rows.Read(BuildDrawerCategory.Soldiers,facts);}catch(Exception e){a=e;}try{rows.ContainsCurrentSelection(selected,facts,observed);}catch(Exception e){b=e;}Check(a!=null&&b!=null&&a.GetType()==b.GetType()&&a.Message==b.Message,"exact catalog exception parity");}finally{em.SetComponentData(session,old);}});
 Case("observed exact membership revalidates scope/world",()=>{var observed=rows.ReadObserved(BuildDrawerCategory.Soldiers,facts);Check(rows.ContainsCurrentSelection(selected,facts,observed),"Same observed member");Check(CatalogMetadataReadScope.Current==null,"Scope disposed");});
 Case("different facts fallback performs original fresh read",()=>{var observed=rows.ReadObserved(BuildDrawerCategory.Soldiers,facts);var restricted=new CatalogPublicFacts(true,true,default,new UiMissionBuildCatalogEntryModel?[0],false,default,false,default,false,default);Check(rows.Read(BuildDrawerCategory.Soldiers,restricted).Length==0,"Restricted fresh read empty");Check(!rows.ContainsCurrentSelection(selected,restricted,observed),"Changed facts must fresh read");});
 Case("different category fallback performs original fresh read",()=>{var observed=rows.ReadObserved(BuildDrawerCategory.Vehicles,facts);Check(rows.ContainsCurrentSelection(selected,facts,observed),"Category fallback");});
 Case("forged issuer cannot inject membership",()=>{var fake=new SourceCatalogRows.ObservedCategory(rows,facts,BuildDrawerCategory.Soldiers,new object(),Array.Empty<BuildDrawerCatalogItem>());Check(rows.ContainsCurrentSelection(selected,facts,fake),"Wrong issuer falls back to actual rows");});
 Case("reused local result still rejects changed phase",()=>{var observed=rows.ReadObserved(BuildDrawerCategory.Soldiers,facts);var s=em.GetComponentData<SkirmishExpandedSessionComponent>(session);var bad=s;bad.Phase=SkirmishSessionPhase.Spawning;em.SetComponentData(session,bad);try{Reject<NotSupportedException>(()=>rows.ContainsCurrentSelection(selected,facts,observed),"Exact current Playing S002 source match/session/catalog singleton required");}finally{em.SetComponentData(session,s);}});
 Case("reused local result still rejects nested scope",()=>{var observed=rows.ReadObserved(BuildDrawerCategory.Soldiers,facts);using(var outer=new CatalogMetadataReadScope(em,store,facts,catalog)){Reject<NotSupportedException>(()=>rows.ContainsCurrentSelection(selected,facts,observed),"Nested source catalog context unsupported");Check(ReferenceEquals(CatalogMetadataReadScope.Current,outer),"Outer scope retained");}});
#endif
 var report=new JObject{["status"]="Passed",["cases"]=Cases,["source_setup"]=SkirmishSetupCompiler.ComputeHash(setup,setup.Seed),["world_created"]=false,["fixture_entities_imported"]=2,["scope"]="Finite imported source catalog+actualoriginalsetup/guards. No paid producer/funding/queue/wholeReadOffer/mission evidence; Core separate realWorldprobe."};using(var f=new FileStream(args[2],FileMode.CreateNew))using(var w=new StreamWriter(f))w.Write(report.ToString(Formatting.Indented));Console.WriteLine("[PaidCategoryGuardControls] result=Passed checks="+Cases.Count+" world=False");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
